package com.rikkeibank.account.service;
import com.rikkeibank.account.dto.*; import com.rikkeibank.account.model.*; import com.rikkeibank.account.repository.*; import java.math.BigDecimal; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException;
@Service public class BankAccountService{private final BankAccountRepository repo;private final AccountTypeRepository typeRepo;private final AccountOperationRepository opRepo;public BankAccountService(BankAccountRepository r,AccountTypeRepository t,AccountOperationRepository o){repo=r;typeRepo=t;opRepo=o;}
 public BankAccount find(Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy tài khoản"));}public List<BankAccount> all(){return repo.findAll();}public List<BankAccount> mine(String username){return repo.findAllByOwnerUsername(username);}
 @Transactional public BankAccount create(BankAccountRequest r){BankAccount a=new BankAccount();a.setAccountNumber(r.accountNumber());a.setOwnerUsername(r.ownerUsername());a.setAccountType(typeRepo.findById(r.accountTypeId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy loại tài khoản")));a.setBalance(r.openingBalance());return repo.save(a);}
 @Transactional public BankAccount update(Long id,BankAccountRequest r){BankAccount a=find(id);a.setAccountNumber(r.accountNumber());a.setOwnerUsername(r.ownerUsername());a.setAccountType(typeRepo.findById(r.accountTypeId()).orElseThrow());return repo.save(a);}
 @Transactional public void delete(Long id){BankAccount a=find(id);a.setActive(false);repo.save(a);}
 @Transactional public AccountBalanceResponse debit(AccountOperationRequest r){return mutate(r,"DEBIT",true);}
 @Transactional public AccountBalanceResponse credit(AccountOperationRequest r){return mutate(r,"CREDIT",false);}
 @Transactional public AccountBalanceResponse compensateDebit(AccountOperationRequest r){return mutate(r,"COMPENSATE_DEBIT",false);}
 @Transactional public AccountBalanceResponse compensateCredit(AccountOperationRequest r){return mutate(r,"COMPENSATE_CREDIT",true);}
 private AccountBalanceResponse mutate(AccountOperationRequest r,String type,boolean subtract){BankAccount a=repo.findByIdForUpdate(r.accountId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy tài khoản"));if(opRepo.existsByOperationIdAndOperationType(r.operationId(),type))return new AccountBalanceResponse(a.getId(),a.getAccountNumber(),a.getBalance());if(!a.isActive())throw new ResponseStatusException(HttpStatus.CONFLICT,"Tài khoản đã bị khóa");if(r.ownerUsername()!=null&&!r.ownerUsername().isBlank()&&!a.getOwnerUsername().equals(r.ownerUsername()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Không được thao tác tài khoản của khách hàng khác");BigDecimal next=subtract?a.getBalance().subtract(r.amount()):a.getBalance().add(r.amount());if(next.signum()<0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Số dư không đủ");a.setBalance(next);repo.save(a);AccountOperation op=new AccountOperation();op.setOperationId(r.operationId());op.setOperationType(type);op.setAccountId(a.getId());opRepo.save(op);return new AccountBalanceResponse(a.getId(),a.getAccountNumber(),a.getBalance());}}
